 for(const [plan,name]of [[a,'source'],[b,'target']]){
  assert.equal(plan.schema,'runtime-install-plan/v1');assert.equal(plan.root,path.join(caseRoot,name));assert.equal(plan.workspaceId,run.selection.workspaceId);assert.equal(plan.projectId,run.selection.projectId);assert.equal(plan.role,'operator');
  assert(!plan.legacyMigration&&!plan.legacyOwnerHost&&!plan.legacyProviders&&!plan.workspaceOperator&&!plan.workspaceSetup,'EX10 independent-service migration may not adopt a legacy Workspace');
 }
 for(const key of ['workspaceId','projectId','principalId','role','credentialExpiresAt','integrationsRef','nodeExecutable','nodeSha256','codex'])assert.deepEqual(a[key],b[key],'Upgrade must preserve source authority and configuration');
 assert.equal(b.distribution.manifestDigest,run.candidate.manifestDigest);assert.equal(b.distribution.archiveDigest,run.candidate.archiveDigest);
 assert.equal(qualification.schema,'runtime-base-qualification-build/v1');assert.equal(qualification.classification,'PRIVATE_EX10_QUALIFICATION_ONLY');assert.equal(qualification.officialRelease,false);assert.equal(qualification.dailyInstallationAllowed,false);assert.equal(qualification.releaseAuthorized,false);assert.equal(qualification.qualificationVersion,'0.9.0-ex10-a');
 assert.deepEqual(fs.readFileSync(path.join(a.distribution.packageRoot,'QUALIFICATION.json')),refs.qualification);
 const originalYaml=refs.originalYaml.toString(),correctedYaml=refs.correctedYaml.toString(),oldDocument=parseDocument(originalYaml),correctedDocument=parseDocument(correctedYaml);assert.deepEqual(oldDocument.errors,[]);assert.deepEqual(correctedDocument.errors,[]);
 const oldModel=oldDocument.toJS(),correctedModel=correctedDocument.toJS();assert.equal(oldModel.config.plan.budget.timeoutSeconds,1);assert.equal(correctedModel.config.plan.budget.timeoutSeconds,1);assert.equal(oldModel.schema,'runtime-project-lifecycle/ex10-a');assert.equal(correctedModel.schema,'runtime-project-lifecycle/v1');assert.equal(oldModel.config.scope.deliveryTargetRef,undefined);assert(correctedModel.config.scope.deliveryTargetRef);
 const extensionIds=model=>model.extensions.map(e=>e.id).sort();assert(oldModel.extensions.length>0);assert(oldModel.extensions.some(e=>e.slot==='legacy-after-plan'));assert.deepEqual(extensionIds(oldModel),extensionIds(correctedModel),'Correction must preserve every project extension');assert(correctedModel.extensions.every(e=>e.slot!=='legacy-after-plan'));
 fs.mkdirSync(cfg.root,{mode:0o700});fs.mkdirSync(caseRoot,{mode:0o700});put(path.join(cfg.root,'campaign.json'),{schema:'runtime-ex10-installed-campaign/v1',runId:run.selection.runId,caseId:c.caseInstanceId,candidateDigest:run.candidateDigest,classification:'PRIVATE_EX10_QUALIFICATION_ONLY'});
 let sequence=0,browser,ui,sourceStarted=false,targetStarted=false,completed=false,originalFailure;
 const retainedReceipts=[];
 const save=(name,value)=>{
  let encoded=JSON.stringify(value);for(const root of [a.root,b.root])for(const secret of credentialValues(root))encoded=encoded.replaceAll(secret,'[REDACTED]');assert(Buffer.byteLength(encoded)<=16700000,'Bounded native evidence record');return run.artifact(name,JSON.parse(encoded));
 };
 const reference=(name,value)=>{const ref=path.join(caseRoot,String(++sequence).padStart(4,'0')+'-'+name+'.json');put(ref,value);save('upgrade-exact-request.json',{ref,sha256:sha(protectedBytes(ref,8388608)),value});return ref;};
